mapper.select:
SELECT id, rate_code, level_code, department_id, department_name, billing_unit, cost_amount, currency, effective_date, expiry_date, status, remark, tenant_id, provider_trace_id, created_at, updated_at, deleted FROM ydsz_rate_internal
WHERE level_code = #{levelCode}

      AND department_id = #{departmentId}
      AND department_id IS NULL

  AND deleted = 0
ORDER BY effective_date DESC
